<template><div class="login"><el-card class="box"><h2>登录职芽</h2><el-form :model="form" @submit.prevent><el-form-item><el-input v-model="form.username" placeholder="用户名" /></el-form-item><el-form-item><el-input v-model="form.password" type="password" placeholder="密码" show-password /></el-form-item><el-button type="primary" class="full" @click="submit">登录</el-button></el-form><p>还没有账号？<router-link to="/register">立即注册</router-link></p></el-card></div></template>
<script setup lang="ts">import { reactive } from 'vue'; import { ElMessage } from 'element-plus'; import { login } from '../../api/auth'; import { useUserStore } from '../../store/user'; import { useRouter } from 'vue-router'; const form=reactive({username:'student01',password:'123456'}); const router=useRouter(); const store=useUserStore(); async function submit(){ try{const res:any=await login(form); store.setToken(res.data.data.token); ElMessage.success('登录成功'); router.push('/home')}catch{ElMessage.error('登录失败，请检查服务')}} </script>
<style scoped>.login{min-height:100vh;display:grid;place-items:center;background:#f4f7fb}.box{width:360px;padding:18px}.box h2{text-align:center}.full{width:100%}p{text-align:center;color:#8795a1}</style>
